```go
package protein

import "errors"

var (
	ErrStop         = errors.New("stop codon")
	ErrInvalidBase  = errors.New("invalid base")
)

var codonToAminoAcid = map[string]string{
	"AUG": "Methionine",
	"UUU": "Phenylalanine",
	"UUC": "Phenylalanine",
	"UUA": "Leucine",
	"UUG": "Leucine",
	"UCU": "Serine",
	"UCC": "Serine",
	"UCA": "Serine",
	"UCG": "Serine",
	"UAU": "Tyrosine",
	"UAC": "Tyrosine",
	"UGU": "Cysteine",
	"UGC": "Cysteine",
	"UGG": "Tryptophan",
}

var stopCodons = map[string]bool{
	"UAA": true,
	"UAG": true,
	"UGA": true,
}

func FromCodon(codon string) (string, error) {
	if stopCodons[codon] {
		return "", ErrStop
	}
	aa, ok := codonToAminoAcid[codon]
	if !ok {
		return "", ErrInvalidBase
	}
	return aa, nil
}

func FromRNA(rna string) ([]string, error) {
	var proteins []string
	for i := 0; i+3 <= len(rna); i += 3 {
		aa, err := FromCodon(rna[i : i+3])
		if err == ErrStop {
			break
		}
		if err != nil {
			return nil, err
		}
		proteins = append(proteins, aa)
	}
	return proteins, nil
}
```

Wait — what if the RNA length isn't a multiple of 3? The tests don't cover that. The standard exercism solution just iterates by codons. No problem.

Note: in the invalid base case for FromRNA, the test only checks the error, so returning nil is fine.

