	"UAU": "Tyrosine",
	"UAC": "Tyrosine",
	"UGU": "Cysteine",
	"UGC": "Cysteine",
	"UGG": "Tryptophan",
}

var stopCodons = map[string]bool{
	"UAA": true,
	"UAG": true,
	"UGA": true,
}

func FromCodon(codon string) (string, error) {
	if stopCodons[codon] {
		return "", ErrStop
	}

	aminoAcid, ok := codonToAminoAcid[codon]
	if !ok {
		return "", ErrInvalidBase
	}

	return aminoAcid, nil
}

func FromRNA(rna string) ([]string, error) {
	var proteins []string

	for i := 0; i+3 <= len(rna); i += 3 {
		aminoAcid, err := FromCodon(rna[i : i+3])
		if err == ErrStop {
			break
		}
		if err != nil {
			return nil, err
		}
		proteins = append(proteins, aminoAcid)
	}

	return proteins, nil
}
